def ROWS(rows, label, widths=(30, 70), head=(("Item", "البند"), ("What the slide says", "ما تقوله الشريحة"))):
    """slide cards (title + text) → bilingual table; rows = [(title_en, title_ar, text_en, text_ar)]"""
    J = lambda x: " ".join(x) if isinstance(x, list) else x
    return T([B(*head[0]), B(*head[1])], [[B(f"**{a}**", f"**{b}**"), B(J(c), J(d))] for a, b, c, d in rows],
             key_cols=[0], widths=list(widths), label_en=label[0], label_ar=label[1])


def TYPE(no, name_en, name_ar, sub_en, sub_ar, steps, how, use, key):
    return [H2(f"**{no}. {name_en}**", f"**{no}. {name_ar}**"),
            C(sub_en, sub_ar),
            FLOW(steps),
            ROWS([("How it works", "طريقة العمل", *how), ("Main use", "الاستعمال الرئيسي", *use), ("Key point", "النقطة المفتاحية", *key)],
                 (f"{name_en}", f"{name_ar}"), (24, 76))]


